        if(r.type.startsWith('policy')||(transfer&&v.dataset)){const plain=notice(editor.review,policySummary(v,r.snapshot_effective));plain.dataset.reviewPolicySummary='';editor.review.append(el('p','Server timezone. Overdue snapshots may be created at the next scheduled check.','zfsm-muted'));}
